<?php require 'config/db.php'; $stmt=$pdo->prepare("SELECT * FROM services WHERE slug=? AND status='published' LIMIT 1");$stmt->execute([$_GET['slug']??'']);$s=$stmt->fetch();if(!$s){http_response_code(404);die('Service not found');}$page_title=$s['title'];include 'includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow">Service Detail</span><h1><?=e($s['title'])?></h1><p class="lead"><?=e($s['excerpt'])?></p></div></section><section class="content-shell"><div class="container split"><div class="form-card"><h2>What this service covers</h2><div class="lead"><?=nl2br(e($s['body']))?></div><a class="btn btn-primary" href="contact.php"><i class="fa-solid fa-paper-plane"></i> Request This Service</a></div><div class="media-frame"><img src="<?=e($s['image_url']?:'assets/img/site/service-1.jpg')?>" alt="<?=e($s['title'])?>"></div></div></section><?php include 'includes/footer.php'; ?>